const input = $input.first().json;
const fromWebhook = input.body && typeof input.body === 'object' && !Array.isArray(input.body);
const raw = fromWebhook ? input.body : input;
return [{ json: {
  intake_raw: raw,
  request_meta: {
    request_id: `invreq_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`,
    received_at: new Date().toISOString(),
    received_via: fromWebhook ? 'webhook' : 'manual_demo'
  }
} }];

// Configure non-secret values in n8n's Variables view. Never put API keys here.
const text = (value, fallback = '') => String(value ?? fallback).trim();
const number = (value, fallback, min, max) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : fallback;
};
const demoValue = text($vars.INVOICEGUARD_DEMO_MODE, 'true').toLowerCase();
const demoMode = !['false', '0', 'no', 'off'].includes(demoValue);

const USER_CONFIG = {
  demo_mode: demoMode,
  max_file_size_bytes: number($vars.INVOICEGUARD_MAX_FILE_SIZE_BYTES, 15728640, 1, 104857600),
  allowed_mime_types: ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'],
  file_fingerprint_ttl_hours: number($vars.INVOICEGUARD_FINGERPRINT_TTL_HOURS, 72, 1, 720),
  processing_lock_minutes: number($vars.INVOICEGUARD_PROCESSING_LOCK_MINUTES, 30, 1, 1440),
  ocr_model: text($vars.INVOICEGUARD_OCR_MODEL, 'mistral-ocr-latest'),
  openrouter_model: text($vars.INVOICEGUARD_OPENROUTER_MODEL, 'openai/gpt-5.1'),
  amount_tolerance: number($vars.INVOICEGUARD_AMOUNT_TOLERANCE, 0.02, 0, 100),
  auto_approve_limit: number($vars.INVOICEGUARD_AUTO_APPROVE_LIMIT, 5000, 0, 1000000000),
  review_risk_threshold: number($vars.INVOICEGUARD_REVIEW_RISK_THRESHOLD, 25, 0, 100),
  block_risk_threshold: number($vars.INVOICEGUARD_BLOCK_RISK_THRESHOLD, 70, 0, 100),
  fuzzy_duplicate_days: number($vars.INVOICEGUARD_FUZZY_DUPLICATE_DAYS, 120, 1, 3650),
  approval_email: text($vars.INVOICEGUARD_APPROVAL_EMAIL, demoMode ? 'finance.manager@example.com' : ''),
  finance_alert_chat_id: text($vars.INVOICEGUARD_TELEGRAM_CHAT_ID, demoMode ? 'DEMO_CHAT_ID' : ''),
  erp_base_url: text($vars.INVOICEGUARD_ERP_BASE_URL, demoMode ? 'https://erp.example.com/api/v1' : '').replace(/\/+$/, ''),
  archive_folder: text($vars.INVOICEGUARD_ARCHIVE_FOLDER, 'Processed/Invoices')
};

if (USER_CONFIG.block_risk_threshold < USER_CONFIG.review_risk_threshold) {
  throw new Error('INVOICEGUARD_BLOCK_RISK_THRESHOLD must be greater than or equal to INVOICEGUARD_REVIEW_RISK_THRESHOLD');
}
if (!demoMode) {
  const missing = [];
  if (!USER_CONFIG.approval_email) missing.push('INVOICEGUARD_APPROVAL_EMAIL');
  if (!USER_CONFIG.finance_alert_chat_id) missing.push('INVOICEGUARD_TELEGRAM_CHAT_ID');
  if (!USER_CONFIG.erp_base_url) missing.push('INVOICEGUARD_ERP_BASE_URL');
  if (missing.length) throw new Error(`Missing live configuration: ${missing.join(', ')}`);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(USER_CONFIG.approval_email)) throw new Error('INVOICEGUARD_APPROVAL_EMAIL is invalid');
  let erpUrl;
  try { erpUrl = new URL(USER_CONFIG.erp_base_url); } catch { throw new Error('INVOICEGUARD_ERP_BASE_URL is invalid'); }
  if (erpUrl.protocol !== 'https:') throw new Error('INVOICEGUARD_ERP_BASE_URL must use HTTPS');
}

return [{ json: { ...$input.first().json, config: USER_CONFIG } }];

const data = $input.first().json;
const raw = data.intake_raw || {};
const clean = (value, max = 500) => String(value ?? '').trim().replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').slice(0, max);
const toNumber = (value) => { const n = Number(value); return Number.isFinite(n) ? n : 0; };
const document = {
  url: clean(raw.document_url || raw.url, 1500),
  file_name: clean(raw.file_name || raw.filename || 'invoice-document', 240),
  mime_type: clean(raw.mime_type || raw.content_type, 120).toLowerCase(),
  size_bytes: Math.max(0, Math.round(toNumber(raw.file_size_bytes || raw.size_bytes))),
  content_sha256: clean(raw.content_sha256, 64).toLowerCase(),
  source: clean(raw.source || 'webhook', 100),
  submitted_by: clean(raw.submitted_by || raw.sender, 180)
};
const errors = [];
let safeUrl = false;
try {
  const parsed = new URL(document.url);
  const host = parsed.hostname.toLowerCase().replace(/^\[|\]$/g, '');
  const blocked = host === 'localhost' || host === '0.0.0.0' || host.endsWith('.local') || host.includes(':') || /^127\./.test(host) || /^10\./.test(host) || /^192\.168\./.test(host) || /^169\.254\./.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host);
  safeUrl = parsed.protocol === 'https:' && !blocked && !parsed.username && !parsed.password;
} catch {}
if (!document.url) errors.push('document_url is required');
else if (!safeUrl) errors.push('document_url must be an allowed HTTPS URL');
if (!data.config.allowed_mime_types.includes(document.mime_type)) errors.push(`unsupported mime_type: ${document.mime_type || 'missing'}`);
if (!document.size_bytes) errors.push('file_size_bytes must be greater than zero');
if (document.size_bytes > data.config.max_file_size_bytes) errors.push(`file exceeds ${data.config.max_file_size_bytes} bytes`);
if (document.content_sha256 && !/^[a-f0-9]{64}$/.test(document.content_sha256)) errors.push('content_sha256 must contain 64 hexadecimal characters');
return [{ json: {
  ...data,
  document,
  validation: { valid: errors.length === 0, errors },
  intake_raw: undefined
} }];

const data = $input.first().json;
return [{ json: {
  success: false,
