const data = $input.first().json;
let canonical = data.document.content_sha256;
if (!canonical) {
  let stableUrl = data.document.url;
  try { const parsed = new URL(stableUrl); parsed.search = ''; parsed.hash = ''; stableUrl = parsed.toString(); } catch {}
  canonical = `${stableUrl}|${data.document.file_name.toLowerCase()}|${data.document.size_bytes}`;
}
let hash = 2166136261;
for (let i = 0; i < canonical.length; i++) { hash ^= canonical.charCodeAt(i); hash = Math.imul(hash, 16777619); }
const fingerprint = data.document.content_sha256 || `file_${(hash >>> 0).toString(16).padStart(8, '0')}`;
const now = Date.now();
const ttl = data.config.file_fingerprint_ttl_hours * 60 * 60 * 1000;
const lock = data.config.processing_lock_minutes * 60 * 1000;
let duplicate = false;
let duplicateOf = null;
if (!data.config.demo_mode) {
  const store = $getWorkflowStaticData('global');
  store.invoiceguard_files = store.invoiceguard_files || {};
  for (const [key, entry] of Object.entries(store.invoiceguard_files)) {
    if (now - Number(entry.updated_at || 0) > ttl) delete store.invoiceguard_files[key];
  }
  const existing = store.invoiceguard_files[fingerprint];
  if (existing) {
    const age = now - Number(existing.updated_at || 0);
    duplicate = existing.status === 'completed' ? age < ttl : age < lock;
    duplicateOf = existing.request_id || null;
  }
  if (!duplicate) store.invoiceguard_files[fingerprint] = { status: 'processing', request_id: data.request_meta.request_id, updated_at: now };
}
return [{ json: { ...data, file_identity: { fingerprint, duplicate, duplicate_of: duplicateOf } } }];

const data = $input.first().json;
