  else if (typeof content === 'string') parsed = JSON.parse(content.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim());
} catch {}
const fallback = { vendor: {}, invoice_number: '', invoice_date: '', due_date: '', currency: '', po_number: '', payment_terms: '', subtotal: 0, tax: 0, total: 0, line_items: [], extraction_confidence: 0 };
return [{ json: {
