const data = $input.first().json;
const raw = data.extraction_raw || {};
const clean = (value, max = 500) => String(value ?? '').trim().replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').slice(0, max);
const money = (value) => { const n = Number(String(value ?? 0).replace(/[^0-9.-]/g, '')); return Number.isFinite(n) ? Math.round(n * 100) / 100 : 0; };
const qty = (value) => { const n = Number(value); return Number.isFinite(n) ? n : 0; };
const isoDate = (value) => /^\d{4}-\d{2}-\d{2}$/.test(String(value ?? '')) ? String(value) : '';
const vendorRaw = raw.vendor || {};
const lineItems = Array.isArray(raw.line_items) ? raw.line_items.slice(0, 100).map(item => ({
  description: clean(item.description, 300),
  sku: clean(item.sku, 100),
  quantity: qty(item.quantity),
  unit_price: money(item.unit_price),
  line_total: money(item.line_total)
})) : [];
const reportedConfidence = Math.min(1, Math.max(0, Number(raw.extraction_confidence) || 0));
const hasOcrConfidence = data.ocr?.confidence !== null && data.ocr?.confidence !== undefined && Number.isFinite(Number(data.ocr.confidence));
const ocrConfidence = hasOcrConfidence ? Math.min(1, Math.max(0, Number(data.ocr.confidence))) : null;
const confidence = ocrConfidence === null ? reportedConfidence : Math.min(reportedConfidence || ocrConfidence, ocrConfidence);
const invoice = {
  vendor: {
    name: clean(vendorRaw.name, 240),
    tax_id: clean(vendorRaw.tax_id, 100).toUpperCase(),
    email: clean(vendorRaw.email, 180).toLowerCase(),
    bank_account_last4: clean(vendorRaw.bank_account_last4, 4)
  },
  invoice_number: clean(raw.invoice_number, 120).toUpperCase(),
  invoice_date: isoDate(raw.invoice_date),
  due_date: isoDate(raw.due_date),
  currency: clean(raw.currency, 3).toUpperCase(),
  po_number: clean(raw.po_number, 120).toUpperCase(),
  payment_terms: clean(raw.payment_terms, 200),
  subtotal: money(raw.subtotal),
  tax: money(raw.tax),
  total: money(raw.total),
  line_items: lineItems,
  extraction_confidence: confidence
};
const criticalMissing = [];
if (!invoice.vendor.name) criticalMissing.push('vendor.name');
if (!invoice.invoice_number) criticalMissing.push('invoice_number');
if (!invoice.invoice_date) criticalMissing.push('invoice_date');
if (!invoice.currency) criticalMissing.push('currency');
if (!(invoice.total > 0)) criticalMissing.push('total');
return [{ json: {
  ...data,
  invoice,
  extraction_validation: { critical_missing: criticalMissing, valid_for_controls: criticalMissing.length === 0 },
  extraction_meta: { ...data.extraction_meta, reported_confidence: reportedConfidence, ocr_confidence: ocrConfidence, effective_confidence: confidence },
  extraction_raw: undefined
} }];

const data = $input.first().json;
const inv = data.invoice;
const normalize = value => String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const days = data.config.fuzzy_duplicate_days;
const tolerance = data.config.amount_tolerance;
const now = Date.now();
const history = data.config.demo_mode ? [
  { invoice_number: 'INV-2026-1001', vendor_key: 'US945550123', currency: 'USD', total: 3200, invoice_date: '2026-08-02', record_id: 'demo_bill_1001' },
  { invoice_number: 'INV-2026-0998', vendor_key: 'US945550123', currency: 'USD', total: 4900, invoice_date: '2026-07-28', record_id: 'demo_bill_0998' }
] : Object.values(($getWorkflowStaticData('global').invoiceguard_history || {}));
const vendorKey = normalize(inv.vendor.tax_id || inv.vendor.name);
const numberKey = normalize(inv.invoice_number);
const editDistance = (a, b) => {
  const row = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let prev = row[0]; row[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = row[j];
      row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return row[b.length];
};
let exact = null;
let near = null;
for (const record of history) {
  const sameVendor = normalize(record.vendor_key) === vendorKey;
  const sameCurrency = String(record.currency || '').toUpperCase() === inv.currency;
  const sameAmount = Math.abs(Number(record.total || 0) - inv.total) <= tolerance;
  const recNumber = normalize(record.invoice_number);
  if (sameVendor && recNumber === numberKey) { exact = record; break; }
  const recDate = Date.parse(record.invoice_date || '');
  const recent = Number.isFinite(recDate) && Math.abs(now - recDate) <= days * 24 * 60 * 60 * 1000;
  if (!near && sameVendor && sameCurrency && sameAmount && recent && editDistance(recNumber, numberKey) <= 1) near = record;
}
return [{ json: {
  ...data,
  invoice_identity: {
    key: `${vendorKey}|${numberKey}|${inv.currency}`,
    exact_duplicate: Boolean(exact),
    near_duplicate: Boolean(near),
    matched_record_id: exact?.record_id || near?.record_id || null,
    match_type: exact ? 'exact' : near ? 'near' : 'none'
  }
} }];

const data = $input.first().json;
return [{ json: {
  ...data,
  erp_context: {
