        { sku: 'SVC-IMP', description: 'Implementation services', ordered_quantity: 1, unit_price: 3000 }
      ]
    },
    goods_receipt: {
      number: 'GR-2026-771',
      received_at: '2026-09-01',
      line_items: [
        { sku: 'GW-200', received_quantity: 2 },
        { sku: 'SVC-IMP', received_quantity: 1 }
      ]
    }
  }
} }];

const data = $input.first().json;
const response = data.data && typeof data.data === 'object' ? data.data : data;
const hasContext = response.purchase_order || response.vendor || response.goods_receipt;
return [{ json: {
