const data = $input.first().json;
const inv = data.invoice;
const ctx = data.erp_context || {};
const po = ctx.purchase_order;
const receipt = ctx.goods_receipt;
const vendor = ctx.vendor;
const tol = data.config.amount_tolerance;
const normalize = value => String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const moneyEqual = (a, b) => Math.abs(Number(a || 0) - Number(b || 0)) <= tol;
const lineSum = Math.round(inv.line_items.reduce((sum, item) => sum + Number(item.line_total || 0), 0) * 100) / 100;
const expectedTotal = Math.round((inv.subtotal + inv.tax) * 100) / 100;
const invoiceDate = Date.parse(inv.invoice_date || '');
const dueDate = Date.parse(inv.due_date || '');
const tomorrow = Date.now() + 24 * 60 * 60 * 1000;
const flags = [];
const add = (code, severity, points, message) => flags.push({ code, severity, points, message });
for (const field of data.extraction_validation.critical_missing) add(`missing_${field.replace(/\./g, '_')}`, 'critical', 40, `Required field is missing: ${field}`);
if (!moneyEqual(expectedTotal, inv.total)) add('invoice_math_mismatch', 'high', 35, `Subtotal + tax (${expectedTotal}) does not equal total (${inv.total})`);
if (inv.line_items.length && !moneyEqual(lineSum, inv.subtotal)) add('line_sum_mismatch', 'high', 25, `Line items (${lineSum}) do not equal subtotal (${inv.subtotal})`);
if (Number.isFinite(invoiceDate) && invoiceDate > tomorrow) add('future_invoice_date', 'medium', 15, 'Invoice date is in the future');
if (Number.isFinite(invoiceDate) && Number.isFinite(dueDate) && dueDate < invoiceDate) add('due_before_invoice', 'high', 25, 'Due date is earlier than invoice date');
if (data.invoice_identity.exact_duplicate) add('exact_duplicate_invoice', 'critical', 100, `Exact duplicate of ${data.invoice_identity.matched_record_id}`);
else if (data.invoice_identity.near_duplicate) add('near_duplicate_invoice', 'high', 60, `Possible duplicate of ${data.invoice_identity.matched_record_id}`);
if (inv.extraction_confidence < 0.75) add('low_extraction_confidence', 'high', 30, `Extraction confidence is ${inv.extraction_confidence}`);
else if (inv.extraction_confidence < 0.9) add('medium_extraction_confidence', 'medium', 15, `Extraction confidence is ${inv.extraction_confidence}`);
if (!po) add('purchase_order_not_found', 'medium', 25, 'No matching purchase order was found');
if (po && !['open', 'approved', 'partially_received'].includes(String(po.status || '').toLowerCase())) add('purchase_order_status', 'high', 30, `PO status is ${po.status || 'unknown'}`);
const invoiceVendorKey = normalize(inv.vendor.tax_id || inv.vendor.name);
const masterVendorKey = normalize(vendor?.tax_id || po?.vendor_tax_id || vendor?.name);
if (po && masterVendorKey && invoiceVendorKey !== masterVendorKey) add('vendor_mismatch', 'critical', 50, 'Invoice vendor does not match the approved vendor');
if (vendor && vendor.approved === false) add('vendor_not_approved', 'critical', 50, 'Vendor is not approved');
if (po && String(po.currency || '').toUpperCase() !== inv.currency) add('currency_mismatch', 'high', 30, 'Invoice currency does not match the PO');
if (po && !moneyEqual(po.total, inv.total)) add('po_total_mismatch', 'high', 30, `Invoice total ${inv.total} does not match PO total ${po.total}`);
const bankInvoice = normalize(inv.vendor.bank_account_last4);
const bankMaster = normalize(vendor?.bank_account_last4);
if (bankInvoice && bankMaster && bankInvoice !== bankMaster) add('bank_account_changed', 'critical', 60, 'Bank account differs from vendor master data');
let receiptComplete = null;
if (po && receipt) {
  receiptComplete = inv.line_items.every(item => {
    const key = normalize(item.sku || item.description);
    const match = (receipt.line_items || []).find(r => normalize(r.sku || r.description) === key);
    return match && Number(match.received_quantity || 0) >= Number(item.quantity || 0);
  });
  if (!receiptComplete) add('goods_not_fully_received', 'high', 30, 'Invoice quantity exceeds received quantity');
} else if (po && !receipt) add('goods_receipt_missing', 'medium', 25, 'No goods receipt was found');
return [{ json: {
  ...data,
  controls: {
    invoice_math_valid: moneyEqual(expectedTotal, inv.total),
    line_sum_valid: !inv.line_items.length || moneyEqual(lineSum, inv.subtotal),
    purchase_order_found: Boolean(po),
    vendor_match: po ? invoiceVendorKey === masterVendorKey : null,
    currency_match: po ? String(po.currency || '').toUpperCase() === inv.currency : null,
    po_total_match: po ? moneyEqual(po.total, inv.total) : null,
    receipt_complete: receiptComplete,
    bank_account_match: bankInvoice && bankMaster ? bankInvoice === bankMaster : null,
    exact_duplicate: data.invoice_identity.exact_duplicate,
    near_duplicate: data.invoice_identity.near_duplicate,
    flags
  }
} }];

const data = $input.first().json;
const riskScore = Math.min(100, data.controls.flags.reduce((sum, flag) => sum + Number(flag.points || 0), 0));
const criticalMissing = data.extraction_validation.critical_missing.length > 0;
const criticalControl = data.controls.flags.some(flag => flag.severity === 'critical');
const blocked = criticalMissing || criticalControl || data.invoice_identity.exact_duplicate || riskScore >= data.config.block_risk_threshold;
const reviewRequired = !blocked && (riskScore >= data.config.review_risk_threshold || data.invoice.total >= data.config.auto_approve_limit || data.invoice.extraction_confidence < 0.9);
const decision = blocked ? 'blocked' : reviewRequired ? 'human_review' : 'auto_approved';
const approvalMessage = [
  `Invoice: ${data.invoice.invoice_number || 'UNKNOWN'}`,
  `Vendor: ${data.invoice.vendor.name || 'UNKNOWN'}`,
  `PO: ${data.invoice.po_number || 'NOT PROVIDED'}`,
  `Amount: ${data.invoice.total.toFixed(2)} ${data.invoice.currency}`,
  `Risk: ${riskScore}/100`,
  `OCR confidence: ${(data.invoice.extraction_confidence * 100).toFixed(0)}%`,
  '',
  'CONTROL FLAGS',
  ...(data.controls.flags.length ? data.controls.flags.map(flag => `- [${flag.severity.toUpperCase()}] ${flag.message}`) : ['- No control failures']),
  '',
  `Document: ${data.document.url}`
].join('\n');
return [{ json: {
  ...data,
  risk: { score: riskScore, level: criticalControl || riskScore >= 70 ? 'critical' : riskScore >= 40 ? 'high' : riskScore >= 20 ? 'medium' : 'low' },
  decision: { status: decision, blocked, review_required: reviewRequired, approval_message: approvalMessage, policy_version: '1.0.0' }
} }];

const base = $('Calculate Risk and Decision').first().json;
