return [{ json: {
  ...base,
  outcome: {
    status: 'blocked',
    approval: { required: false, approved: false, reason: 'blocked_by_policy' },
    finance_alert_status: base.config.demo_mode ? 'simulated' : (input.ok === false || input.error ? 'failed' : 'sent'),
    erp_draft: null
  }
} }];

const data = $input.first().json;
return [{ json: {
