const lower = JSON.stringify(response).toLowerCase();
const status = String(response.approvalStatus ?? response.data?.approvalStatus ?? response.response ?? '').toLowerCase();
const approved = response.approved === true || response.data?.approved === true || ['approved', 'approve'].includes(status) || lower.includes('\"approved\":true');
const rejected = response.approved === false || response.data?.approved === false || ['rejected', 'declined', 'reject', 'decline'].includes(status) || lower.includes('\"approved\":false') || lower.includes('\"rejected\":true');
return [{ json: {
  ...base,
  approval: {
    required: true,
    approved: approved && !rejected,
    method: 'gmail_human_review',
    decided_at: new Date().toISOString(),
    raw_status: approved && !rejected ? 'approved' : rejected ? 'rejected' : 'unrecognized_or_timed_out'
  }
} }];

