  ...base,
  outcome: {
    status: 'draft_created',
    approval: base.approval,
    finance_alert_status: 'not_required',
    erp_draft: { provider: 'live_erp', bill_id: billId, status: api.status || 'draft', created_at: api.created_at || new Date().toISOString() }
  }
