const data = $input.first().json;
const now = new Date().toISOString();
const processingEventId = `processing_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
if (!data.config.demo_mode) {
  const store = $getWorkflowStaticData('global');
  store.invoiceguard_files = store.invoiceguard_files || {};
  store.invoiceguard_files[data.file_identity.fingerprint] = { status: 'completed', request_id: data.request_meta.request_id, outcome: data.outcome.status, updated_at: Date.now() };
  if (data.outcome.status === 'draft_created') {
    store.invoiceguard_history = store.invoiceguard_history || {};
    store.invoiceguard_history[data.invoice_identity.key] = {
      invoice_number: data.invoice.invoice_number,
      vendor_key: data.invoice.vendor.tax_id || data.invoice.vendor.name,
      currency: data.invoice.currency,
      total: data.invoice.total,
      invoice_date: data.invoice.invoice_date,
      record_id: data.outcome.erp_draft?.bill_id || processingEventId
    };
  }
  store.invoiceguard_metrics = store.invoiceguard_metrics || {};
  const day = now.slice(0, 10);
  store.invoiceguard_metrics[day] = store.invoiceguard_metrics[day] || { processed: 0, drafts: 0, blocked: 0, rejected: 0 };
  store.invoiceguard_metrics[day].processed += 1;
  if (data.outcome.status === 'draft_created') store.invoiceguard_metrics[day].drafts += 1;
  if (data.outcome.status === 'blocked') store.invoiceguard_metrics[day].blocked += 1;
  if (data.outcome.status === 'rejected_by_human') store.invoiceguard_metrics[day].rejected += 1;
}
return [{ json: {
  success: data.outcome.status === 'draft_created',
  status: data.config.demo_mode ? `demo_${data.outcome.status}` : data.outcome.status,
  request_id: data.request_meta.request_id,
  processing_event_id: processingEventId,
  file: { name: data.document.file_name, fingerprint: data.file_identity.fingerprint, archive_target: data.config.archive_folder },
  invoice: {
    number: data.invoice.invoice_number,
    vendor: data.invoice.vendor.name,
    vendor_tax_id: data.invoice.vendor.tax_id,
    po_number: data.invoice.po_number,
    invoice_date: data.invoice.invoice_date,
    due_date: data.invoice.due_date,
    currency: data.invoice.currency,
    subtotal: data.invoice.subtotal,
    tax: data.invoice.tax,
    total: data.invoice.total,
    line_item_count: data.invoice.line_items.length
  },
  extraction: { provider: data.extraction_meta.provider, effective_confidence: data.invoice.extraction_confidence, reported_confidence: data.extraction_meta.reported_confidence, ocr_provider: data.ocr.provider, ocr_confidence: data.extraction_meta.ocr_confidence },
  duplicate_check: data.invoice_identity,
  controls: data.controls,
  risk: data.risk,
  policy_decision: data.decision.status,
  approval: data.outcome.approval,
  erp_draft: data.outcome.erp_draft,
  finance_alert_status: data.outcome.finance_alert_status,
  processed_at: now
} }];
